    @DisplayName("Delete")
    @Nested
    class Delete {

        @Test
        void delete_accessWithComponents_successWhenForced() throws Exception {
            Mockito.reset(serviceAccessRepository, serviceComponentRepository, serviceTagRepository, serviceActivationRepository);

            doNothing().when(serviceTagRepository).deleteOrphansByService(5L);
            doNothing().when(serviceActivationRepository).deleteOrphansByService(5L);
            doNothing().when(serviceAccessRepository).deleteById(5L);
            doNothing().when(serviceTagRepository).deleteOrphansByService(4L);
            doNothing().when(serviceActivationRepository).deleteOrphansByService(4L);

            MultiValueMap<String, String> params = new LinkedMultiValueMap<>();
            params.add("forced", "true");
            mockMvc.perform(delete(ROUTE_SERVICE + "/5")
                            .contentType(MediaType.APPLICATION_JSON)
                            .params(params))
                    .andDo(print())
                    .andExpect(status().isNoContent());

            verify(serviceTagRepository).deleteOrphansByService(5L);
            verify(serviceActivationRepository).deleteOrphansByService(5L);
            verify(serviceAccessRepository).deleteById(5L);
            verify(serviceTagRepository).deleteOrphansByService(4L);
            verify(serviceActivationRepository).deleteOrphansByService(4L);
        }

        @Test
        void delete_accessWithComponents_failureIfComponents() throws Exception {
            mockMvc.perform(delete(ROUTE_SERVICE + "/5"))
                    .andDo(print())
                    .andExpect(status().isBadRequest())
                    .andExpect(content().json("{\"error\": \"Service '5' is linked to service component(s) thus cannot be deleted\"}"));
        }

        @Test
        void delete_successComponent() throws Exception {
            doNothing().when(serviceTagRepository).deleteOrphansByService(4L);
            doNothing().when(serviceActivationRepository).deleteOrphansByService(4L);
            doNothing().when(serviceComponentRepository).deleteById(4L);

            mockMvc.perform(delete(ROUTE_SERVICE + "/4"))
                    .andDo(print())
                    .andExpect(status().isNoContent());

            verify(serviceTagRepository).deleteOrphansByService(4L);
            verify(serviceActivationRepository).deleteOrphansByService(4L);
            verify(serviceComponentRepository).deleteById(4L);
        }

        @Test
        void delete_failureIfWrongStateComponent() throws Exception {
            mockMvc.perform(delete(ROUTE_SERVICE + "/2"))
                    .andDo(print())
                    .andExpect(status().isBadRequest())
                    .andExpect(content().json("{\"status\":400,\"error\":\"Service '2' cannot be deleted because it is not in status CANCELED or DEACTIVATED\"}"));
        }

        @Test
        void delete_failureIfParentService() throws Exception {
            mockMvc.perform(delete(ROUTE_SERVICE + "/3"))
                    .andDo(print())
                    .andExpect(status().isBadRequest())
                    .andExpect(content().json("{\"status\":400,\"error\":\"Service '3' is a parent thus cannot be deleted\"}"));
        }

        @Test
        void delete_failureIfWrongStateAccess() throws Exception {
            mockMvc.perform(delete(ROUTE_SERVICE + "/2"))
                    .andDo(print())
                    .andExpect(status().isBadRequest())
                    .andExpect(content().json("{\"status\":400,\"error\":\"Service '2' cannot be deleted because it is not in status CANCELED or DEACTIVATED\"}"));
        }

        @Test
        void delete_missing() throws Exception {
            mockMvc.perform(delete(ROUTE_SERVICE + "/99"))
                    .andDo(print())
                    .andExpect(status().isNotFound())
                    .andExpect(content().json("{\"status\":404,\"error\":\"Service with ID '99' was not found\"}"));
        }
    }

