        @Test
        void changeTags_failureIfActivityInconsistency() throws Exception {
            mockMvc.perform(patch(ROUTE_SERVICE + "/2/changetags")
                            .contentType(MediaType.APPLICATION_JSON_VALUE)
                            .content("{\"changeTags\": [{ \"tagCode\": \"HAXACC\", \"tagAction\": \"ADD\"}]}"))
                    .andDo(print())
                    .andExpect(status().isBadRequest())
                    .andExpect(content().json("{\"status\":400,\"error\":\"Provisioning tag 'HAXACC' has activity 'MOBILE' that does not match service activity 'TELEPHONY'\"}"));
        }

